"""Bookshelf: a small app built to be tested.

Users register, log in and keep a private list of books. There is a JSON API
under /api and a server-rendered UI on top of the same logic.
"""

import hashlib
import os
import secrets
import sqlite3
from contextlib import contextmanager
from datetime import date
from pathlib import Path

from fastapi import Cookie, Depends, FastAPI, Form, Header, HTTPException, Request, Response
from fastapi.responses import RedirectResponse
from fastapi.templating import Jinja2Templates
from pydantic import BaseModel, Field

DB_PATH = os.environ.get("DB_PATH", "bookshelf.db")

app = FastAPI(title="Bookshelf")
templates = Jinja2Templates(directory=Path(__file__).parent / "templates")

SCHEMA = """
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    pw_hash TEXT NOT NULL,
    salt TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
    token TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY,
    owner_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    year INTEGER
);
"""


@contextmanager
def db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        yield conn
        conn.commit()
    finally:
        conn.close()


with db() as _conn:
    _conn.executescript(SCHEMA)


# --- models and validation -------------------------------------------------

class Credentials(BaseModel):
    username: str = Field(min_length=3, max_length=30)
    password: str = Field(min_length=6, max_length=100)


class BookIn(BaseModel):
    title: str
    author: str
    year: int | None = None


def validate_book(book: BookIn) -> None:
    if not book.title.strip():
        raise HTTPException(422, "Title must not be blank")
    if not book.author.strip():
        raise HTTPException(422, "Author must not be blank")
    if len(book.title) > 200 or len(book.author) > 100:
        raise HTTPException(422, "Title or author is too long")
    if book.year is not None:
        this_year = date.today().year
        if not 1 <= book.year <= this_year + 1:
            raise HTTPException(422, f"Year must be between 1 and {this_year}")


# --- users and sessions ----------------------------------------------------

def hash_password(password: str, salt: str) -> str:
    return hashlib.pbkdf2_hmac("sha256", password.encode(), bytes.fromhex(salt), 100_000).hex()


def create_user(username: str, password: str) -> int:
    salt = secrets.token_hex(16)
    with db() as conn:
        try:
            cur = conn.execute(
                "INSERT INTO users (username, pw_hash, salt) VALUES (?, ?, ?)",
                (username, hash_password(password, salt), salt),
            )
        except sqlite3.IntegrityError:
            raise HTTPException(409, "Username already taken")
        return cur.lastrowid


def start_session(username: str, password: str) -> str | None:
    with db() as conn:
        user = conn.execute("SELECT * FROM users WHERE username = ?", (username,)).fetchone()
        if user is None or not secrets.compare_digest(
            user["pw_hash"], hash_password(password, user["salt"])
        ):
            return None
        token = secrets.token_urlsafe(32)
        conn.execute("INSERT INTO sessions (token, user_id) VALUES (?, ?)", (token, user["id"]))
        return token


def user_from_token(token: str | None) -> sqlite3.Row | None:
    if not token:
        return None
    with db() as conn:
        return conn.execute(
            "SELECT users.id, users.username FROM sessions JOIN users ON users.id = sessions.user_id "
            "WHERE sessions.token = ?",
            (token,),
        ).fetchone()


def api_user(authorization: str | None = Header(default=None)) -> sqlite3.Row:
    token = authorization.removeprefix("Bearer ").strip() if authorization else None
    user = user_from_token(token)
    if user is None:
        raise HTTPException(401, "Not authenticated")
    return user


def page_user(session: str | None = Cookie(default=None)) -> sqlite3.Row | None:
    return user_from_token(session)


# --- books -----------------------------------------------------------------

def book_dict(row: sqlite3.Row) -> dict:
    return {"id": row["id"], "title": row["title"], "author": row["author"], "year": row["year"]}


def list_books(user_id: int) -> list[dict]:
    with db() as conn:
        rows = conn.execute("SELECT * FROM books WHERE owner_id = ? ORDER BY id", (user_id,)).fetchall()
        return [book_dict(r) for r in rows]


def insert_book(user_id: int, book: BookIn) -> dict:
    validate_book(book)
    with db() as conn:
        cur = conn.execute(
            "INSERT INTO books (owner_id, title, author, year) VALUES (?, ?, ?, ?)",
            (user_id, book.title, book.author, book.year),
        )
        return {"id": cur.lastrowid, **book.model_dump()}


def get_own_book(user_id: int, book_id: int) -> dict:
    with db() as conn:
        row = conn.execute(
            "SELECT * FROM books WHERE id = ? AND owner_id = ?", (book_id, user_id)
        ).fetchone()
    if row is None:
        raise HTTPException(404, "Book not found")
    return book_dict(row)


# --- JSON API --------------------------------------------------------------

@app.get("/health")
def health():
    return {"status": "ok"}


@app.post("/api/users", status_code=201)
def api_register(creds: Credentials):
    user_id = create_user(creds.username, creds.password)
    return {"id": user_id, "username": creds.username}


@app.post("/api/login")
def api_login(creds: Credentials):
    token = start_session(creds.username, creds.password)
    if token is None:
        raise HTTPException(401, "Invalid username or password")
    return {"token": token}


@app.get("/api/books")
def api_list_books(user=Depends(api_user)):
    return list_books(user["id"])


@app.post("/api/books", status_code=201)
def api_create_book(book: BookIn, user=Depends(api_user)):
    return insert_book(user["id"], book)


@app.get("/api/books/{book_id}")
def api_get_book(book_id: int, user=Depends(api_user)):
    return get_own_book(user["id"], book_id)


@app.put("/api/books/{book_id}")
def api_update_book(book_id: int, book: BookIn, user=Depends(api_user)):
    get_own_book(user["id"], book_id)
    validate_book(book)
    with db() as conn:
        conn.execute(
            "UPDATE books SET title = ?, author = ?, year = ? WHERE id = ?",
            (book.title, book.author, book.year, book_id),
        )
    return {"id": book_id, **book.model_dump()}


@app.delete("/api/books/{book_id}", status_code=204)
def api_delete_book(book_id: int, user=Depends(api_user)):
    get_own_book(user["id"], book_id)
    with db() as conn:
        conn.execute("DELETE FROM books WHERE id = ?", (book_id,))
    return Response(status_code=204)


# --- UI --------------------------------------------------------------------

def logged_in_redirect(token: str) -> RedirectResponse:
    response = RedirectResponse("/books", status_code=303)
    response.set_cookie("session", token, httponly=True, samesite="lax")
    return response


def render_auth(request: Request, mode: str, error: str | None = None, username: str = "", status_code: int = 200):
    heading = "Log in" if mode == "login" else "Register"
    return templates.TemplateResponse(
        request,
        "auth.html",
        {"heading": heading, "action": f"/{mode}", "error": error, "username_value": username},
        status_code=status_code,
    )


def render_books(request: Request, user, error: str | None = None, form: dict | None = None, status_code: int = 200):
    return templates.TemplateResponse(
        request,
        "books.html",
        {
            "username": user["username"],
            "books": list_books(user["id"]),
            "error": error,
            "form": form or {"title": "", "author": "", "year": ""},
        },
        status_code=status_code,
    )


@app.get("/")
def home():
    return RedirectResponse("/books", status_code=303)


@app.get("/login")
def login_page(request: Request):
    return render_auth(request, "login")


@app.post("/login")
def login_submit(request: Request, username: str = Form(""), password: str = Form("")):
    token = start_session(username, password)
    if token is None:
        return render_auth(request, "login", "Invalid username or password", username, status_code=401)
    return logged_in_redirect(token)


@app.get("/register")
def register_page(request: Request):
    return render_auth(request, "register")


@app.post("/register")
def register_submit(request: Request, username: str = Form(""), password: str = Form("")):
    if not 3 <= len(username) <= 30 or len(password) < 6:
        return render_auth(
            request, "register", "Username needs 3-30 characters and password at least 6", username, 422
        )
    try:
        create_user(username, password)
    except HTTPException as e:
        return render_auth(request, "register", e.detail, username, e.status_code)
    return logged_in_redirect(start_session(username, password))


@app.post("/logout")
def logout(session: str | None = Cookie(default=None)):
    if session:
        with db() as conn:
            conn.execute("DELETE FROM sessions WHERE token = ?", (session,))
    response = RedirectResponse("/login", status_code=303)
    response.delete_cookie("session")
    return response


@app.get("/books")
def books_page(request: Request, user=Depends(page_user)):
    if user is None:
        return RedirectResponse("/login", status_code=303)
    return render_books(request, user)


@app.post("/books")
def books_add(
    request: Request,
    title: str = Form(""),
    author: str = Form(""),
    year: str = Form(""),
    user=Depends(page_user),
):
    if user is None:
        return RedirectResponse("/login", status_code=303)
    form = {"title": title, "author": author, "year": year}
    try:
        parsed_year = int(year) if year.strip() else None
    except ValueError:
        return render_books(request, user, "Year must be a number", form, status_code=422)
    try:
        insert_book(user["id"], BookIn(title=title, author=author, year=parsed_year))
    except HTTPException as e:
        return render_books(request, user, e.detail, form, status_code=e.status_code)
    return RedirectResponse("/books", status_code=303)


@app.post("/books/{book_id}/delete")
def books_delete(book_id: int, user=Depends(page_user)):
    if user is None:
        return RedirectResponse("/login", status_code=303)
    get_own_book(user["id"], book_id)
    with db() as conn:
        conn.execute("DELETE FROM books WHERE id = ?", (book_id,))
    return RedirectResponse("/books", status_code=303)
